-- One-time backfill of outage_communication, for the DEV instance ONLY.
--
-- *** THIS IS NOT A MIGRATION AND MUST NOT BECOME ONE. *** The rows below are
-- dev content -- lorem ipsum, localhost links, one author. Running them
-- against production would insert dev text onto the public status page.
--
-- Produced by discovery PASS 17 in
--   integrations/csm-flow-service/docs/servicenow-discovery/
--     44-outage-cloud-status-flows.js
-- which reads sys_journal_field for element u_external_outage_communications
-- and emits these statements. Run that pass against whichever ServiceNow
-- instance a given environment is migrating from, and apply ITS output there.
--
-- Why a table rather than the existing outage.external_outage_communications
-- column: PASS 17 measured 17 entries across 7 outages, 4 of which carry
-- more than one and one of which carries five. A single column cannot hold
-- a list, and the endpoint publishes them newest-first with timestamps.
-- *** ONE TRANSACTION, BECAUSE THE FIRST STATEMENT IS A DELETE. *** Every
-- INSERT below references an outage through a foreign key. Without a
-- transaction, one missing outage fails its INSERT after the DELETE has
-- already committed, leaving the table empty or half filled -- and the
-- migration's own comment calls this table first-class data after cutover.
-- Run against the wrong database and an unwrapped script wipes real
-- customer-facing updates with no way back.
BEGIN;

DELETE FROM outage_communication;

-- *** ONE LINE PER STATEMENT, WITH \r AND \n ESCAPED (Postgres E'' strings).
-- *** The journal values are HTML with CRLF line endings. An earlier version
-- of this file wrote them as raw multi-line literals, and copying those
-- through a terminal silently dropped every carriage return -- which was
-- measured: the backfill differed from the live API on exactly three
-- outages, and the whole delta was missing \r. Keep each statement on one
-- line so the whitespace survives transit.
INSERT INTO outage_communication (outage_id, comment, created_on, created_by) VALUES (E'26a2917a-1bc5-b210-0bb3-da47b04bcb0f'::uuid, E'[code]<p><strong>Investigating</strong></p>\r\n<p><span style="color: rgb(0, 0, 0); font-family: \'Open Sans\', Arial, sans-serif; font-size: 14px; text-align: justify; white-space: normal; background-color: rgb(255, 255, 255); float: none; display: inline;">It is a long established fact that a reader will be distracted by the readable content of a page when looking at its layout. The point of using Lorem Ipsum is that it has a more-or-less normal distribution of letters, as opposed to using \'Content here, content here\', making it look like readable English. Many desktop publishing packages and web page editors now use Lorem Ipsum as their default model text, and a search for \'lorem ipsum\' will uncover many web sites still in their infancy. Various versions have evolved over the years, sometimes by accident, sometimes on purpose (injected humour and the like).</span></p>[/code]', E'2025-11-10 05:09:38'::timestamptz, E'athiththan@wso2.com');
INSERT INTO outage_communication (outage_id, comment, created_on, created_by) VALUES (E'606f5cc0-1b9b-72d0-0bb3-da47b04bcbbc'::uuid, E'[code]<p>Mitigations were applied by the Engineering Team to the respective feature.</p>[/code]', E'2026-05-11 06:52:59'::timestamptz, E'athiththan@wso2.com');
INSERT INTO outage_communication (outage_id, comment, created_on, created_by) VALUES (E'606f5cc0-1b9b-72d0-0bb3-da47b04bcbbc'::uuid, E'[code]<p>The incident was discovered by the Engineering team responsible for this feature.</p>[/code]', E'2026-05-11 06:51:49'::timestamptz, E'athiththan@wso2.com');
