INSERT INTO outage_communication (outage_id, comment, created_on, created_by) VALUES (E'79adad2d-1b45-fa10-0bb3-da47b04bcb46'::uuid, E'[code]<p><strong>Update</strong></p>\r\n<p><strong style="margin: 0px; padding: 0px; color: rgb(0, 0, 0); font-family: \'Open Sans\', Arial, sans-serif; font-size: 14px; text-align: justify; white-space: normal; background-color: rgb(255, 255, 255);">Lorem Ipsum</strong><span style="color: rgb(0, 0, 0); font-family: \'Open Sans\', Arial, sans-serif; font-size: 14px; text-align: justify; white-space: normal; background-color: rgb(255, 255, 255); float: none; display: inline;">&nbsp;is simply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry\'s standard dummy text ever since the 1500s, when an unknown printer took a galley of type and scrambled it to make a type specimen book. It has survived not only five centuries, but also the leap into electronic typesetting, remaining essentially unchanged. It was popularised in the 1960s with the release of Letraset sheets containing Lorem Ipsum passages, and more recently with desktop publishing software like Aldus PageMaker including versions of Lorem Ipsum.</span></p>\r\n<p><span style="color: rgb(0, 0, 0); font-family: \'Open Sans\', Arial, sans-serif; font-size: 14px; text-align: justify; white-space: normal; background-color: rgb(255, 255, 255); float: none; display: inline;"><span style="color: rgb(0, 0, 0); font-family: \'Open Sans\', Arial, sans-serif; font-size: 14px; text-align: justify; white-space: normal; background-color: rgb(255, 255, 255); float: none; display: inline;">Contrary to popular belief, Lorem Ipsum is not simply random text. It has roots in a piece of classical Latin literature from 45 BC, making it over 2000 years old. Richard McClintock, a Latin professor at Hampden-Sydney College in Virginia, looked up one of the more obscure Latin words, consectetur, from a Lorem Ipsum passage, and going through the cites of the word in classical literature, discovered the undoubtable source. Lorem Ipsum comes from sections 1.10.32 and 1.10.33 of "de Finibus Bonorum et Malorum" (The Extremes of Good and Evil) by Cicero, written in 45 BC. This book is a treatise on the theory of ethics, very popular during the Renaissance. The first line of Lorem Ipsum, "Lorem ipsum dolor sit amet..", comes from a line in section 1.10.32.</span></span></p>[/code]', E'2025-11-07 02:36:44'::timestamptz, E'athiththan@wso2.com');
INSERT INTO outage_communication (outage_id, comment, created_on, created_by) VALUES (E'79adad2d-1b45-fa10-0bb3-da47b04bcb46'::uuid, E'[code]<p><span style="font-family: verdana, geneva;"><strong>Resolved</strong></span></p>\r\n<p><span style="font-family: verdana, geneva;">The incident has been mitigated by applying hot-fixes to the necessary components.</span></p>\r\n<p><span style="font-family: verdana, geneva;">More details can be found in <a title="Asgardeo Status Page" href="http://localhost:3000/history" target="_blank" rel="noopener">here</a>.</span></p>[/code]', E'2025-11-07 02:29:51'::timestamptz, E'athiththan@wso2.com');
INSERT INTO outage_communication (outage_id, comment, created_on, created_by) VALUES (E'79adad2d-1b45-fa10-0bb3-da47b04bcb46'::uuid, E'[code]<p style="box-sizing: border-box; margin-top: 0px; color: rgb(21, 25, 32); font-family: Lato, Arial, sans-serif; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);"><span style="font-family: \'times new roman\', times;"><strong style="box-sizing: border-box;">Update</strong></span></p>\r\n<p style="box-sizing: border-box; color: rgb(21, 25, 32); font-family: Lato, Arial, sans-serif; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);"><span style="font-family: \'times new roman\', times;">This is to provide an update on the ongoing service disruption.</span></p>\r\n<p style="box-sizing: border-box; margin-bottom: 0px; color: rgb(21, 25, 32); font-family: Lato, Arial, sans-serif; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);"><span style="font-family: \'times new roman\', times;">We\'ll provide an update soon.</span></p>[/code]', E'2025-11-07 02:25:22'::timestamptz, E'athiththan@wso2.com');
INSERT INTO outage_communication (outage_id, comment, created_on, created_by) VALUES (E'79adad2d-1b45-fa10-0bb3-da47b04bcb46'::uuid, E'[code]<p>This another comment from the Outage itself. Providing an update about the outage and its status. This update message contains spaces,&nbsp;</p>\r\n<p>Newlines</p>\r\n<p><strong>Bold,&nbsp;</strong><em>Italic,&nbsp;</em>and <span style="text-decoration: underline;">underline.</span> Also, this contains the following points</p>\r\n<ol>\r\n<li>One</li>\r\n<li>Two</li>\r\n</ol>\r\n<p>Also, some bullet points</p>\r\n<ul>\r\n<li>One</li>\r\n<li>Two</li>\r\n<li>Three</li>\r\n</ul>\r\n<p>This to check the rendering at the Frontend when using the HTML inputs for the Journals.</p>\r\n<p>Thanks</p>[/code]', E'2025-11-06 10:18:04'::timestamptz, E'athiththan@wso2.com');
INSERT INTO outage_communication (outage_id, comment, created_on, created_by) VALUES (E'79adad2d-1b45-fa10-0bb3-da47b04bcb46'::uuid, E'[code]<p>This is an external comment added in Outage: OUT0001856</p>[/code]', E'2025-11-06 09:54:40'::timestamptz, E'athiththan@wso2.com');
